const norm = v => (v && typeof v === 'object') ? v.name : v;
return $input.all()
  .map(it => it.json)
  .filter(r => {
    const p = norm(r.Pertinence);
    const note = r['Note rôle'];
    return (p === 'Haute' || p === 'Moyenne') && !(note && String(note).trim());
  })
  .map(r => ({ json: {
    id: r.id, jobId: r.jobId, poste: r.Poste, employeur: r.Employeur,
    lieu: r.Lieu, pertinence: norm(r.Pertinence), url: r.URL
  }}));

const rec = $('Filtrer à enrichir').item.json;
const html = ($json && ($json.data || $json.body)) || '';
const clean = s => s
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ').trim();
let desc = '';
const i = html.indexOf('show-more-less-html__markup');
if (i >= 0) {
  let chunk = html.slice(i, i + 14000).replace(/show-more-less-html__markup[^>]*>/, '');
  const cut = chunk.search(/show-more-less__button|<\/section>/);
  if (cut > 0) chunk = chunk.slice(0, cut);
  desc = clean(chunk);
}
const crit = [];
const re = /job-criteria-subheader[^>]*>([\s\S]*?)<\/h3>[\s\S]*?job-criteria-text[^>]*>([\s\S]*?)<\/span>/g;
let m;
while ((m = re.exec(html))) crit.push(clean(m[1]) + ': ' + clean(m[2]));
return { json: { ...rec, descText: desc, criteres: crit.join(' | '), ok: desc.length > 200 } };

const PROFIL = `Profil candidat : consultant senior independant, 25 ans d'experience, 100% assurance & finance. Cherche mission freelance/contract/interim (CDI senior finance possible), full remote ou hybride privilegie, TJM >= 1000 EUR/j. Ouvert a l'international en remote (EMEA, Amerique du Nord, APAC).`;
const r = $json;
const prompt = `${PROFIL}

Voici une offre d'emploi. Redige DEUX notes courtes en francais, factuelles, pour aider ce candidat a decider de postuler.

OFFRE : ${r.poste} — ${r.employeur} — ${r.lieu || 'lieu n.c.'}
CRITERES LINKEDIN : ${r.criteres || 'n.c.'}
DESCRIPTION :
${(r.descText || '').slice(0, 6000)}

Reponds UNIQUEMENT avec un objet JSON, sans texte autour :
{"note_role":"3 a 5 phrases : de quoi parle le poste, missions cles, seniorite, et en quoi il matche ou non le profil sur le FOND du role","note_criteres":"3 a 5 puces separees par des retours a la ligne, chaque ligne prefixee '- ' : pour chaque critere cle du recruteur (seniorite, type de contrat, secteur, competences, langue, localisation/remote) indique match ou ecart vs le profil"}`;
return { json: { prompt, id: r.id, jobId: r.jobId, pertinence: r.pertinence } };

const rec = $('Prépa prompt notes').item.json;
let role = '', crit = '';
try {
  const txt = ($json && $json.content && $json.content[0] && $json.content[0].text) || '';
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) { const o = JSON.parse(m[0]); role = o.note_role || ''; crit = o.note_criteres || ''; }
} catch (e) { /* laisse vide -> retente au prochain run */ }
if (!role && !crit) return null;
return { json: { id: rec.id, noteRole: role, noteCriteres: crit, preparer: rec.pertinence === 'Haute' } };

// Prépa scoring — lit le barème depuis GitHub (via Fetch barème)
const upstream = $json; // {id, noteRole, noteCriteres, preparer} from Parser notes
const rec = $('Prépa prompt notes').item.json; // {poste, employeur, lieu, pertinence, description}

// Barème fetchable: texte brut depuis GitHub (mis à jour par sync_bareme.sh après modif Excel)
const baremeNode = $('Fetch barème').item.json;
// Le nœud HTTP retourne le texte dans .data (string) ou dans le body
const BAREME = (baremeNode.data || baremeNode.body || JSON.stringify(baremeNode)).slice(0, 6000);

const hasDesc = rec.description && rec.description.length > 100;
const descPart = hasDesc
  ? '\nDescription (extrait, ≤4000 c.) :\n' + rec.description.slice(0, 4000)
  : '\n(Fiche de poste non disponible — score basé sur titre + employeur + lieu uniquement)';

const prompt = BAREME + '\n\nOFFRE À ÉVALUER :\n' +
  'Poste : ' + (rec.poste || '(non renseigné)') + '\n' +
  'Employeur : ' + (rec.employeur || '(non renseigné)') + '\n' +
  'Lieu : ' + (rec.lieu || '(non renseigné)') + '\n' +
  'Pertinence pré-classifiée : ' + (rec.pertinence || 'non définie') +
  descPart;

return { json: { ...upstream, prompt } };

// Parser score — extrait JSON de la réponse Claude
const upstream = $('Prépa prompt scoring').item.json;
const txt = ($json && $json.content && $json.content[0] && $json.content[0].text) || '';

let score = null, signaux = [], justification = '';
try {
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) {
    const o = JSON.parse(m[0]);
    const raw = typeof o.score === 'number' ? o.score : parseInt(o.score, 10);
    score = isNaN(raw) ? null : Math.min(100, Math.max(0, raw));
    signaux = Array.isArray(o.signaux) ? o.signaux : [];
    justification = o.justification || '';
  }
} catch (e) { /* score reste null, sera ignoré par Écrire notes */ }

return { json: {
  id: upstream.id,
  noteRole: upstream.noteRole,
  noteCriteres: upstream.noteCriteres,
  preparer: upstream.preparer,
  score,
  scoreSignaux: signaux.join(' | '),
  scoreJustification: justification
}};

